import {NextIntlClientProvider} from 'next-intl';
import en from '../../messages/en.json';
import {CompanyRows} from '../../app/admin/organization/company-rows';

const labels={active:'Active',archived:'Archived',empty:'No matching companies',view:'View',edit:'Edit',archive:'Archive',unarchive:'Unarchive',registration:en.admin.organization.registration};
export function CompanyRegistrationPreview(){return <NextIntlClientProvider locale="en" messages={en}><main data-ui-theme="atelier" className="p-4"><h1 className="mb-4 text-xl font-semibold">Companies · statutory registration</h1><div className="max-w-full overflow-x-auto"><table className="w-full text-sm"><thead><tr>{['Code','Legal name','Reg. no.','Statutory','Parent company','Status','Actions'].map((t,i)=><th key={t} className={i===0?'hidden p-3 text-left sm:table-cell':'p-3 text-left'}>{t}</th>)}</tr></thead><tbody><CompanyRows labels={labels} archiveAction={()=>{}} rows={[{id:'demo-a',code:'DEMO-A',name:'Sample employer with a long legal name',registrationNo:null,parentId:'demo-group',parentName:'Sample business group',archived:false,statutoryStatus:'missing'},{id:'demo-b',code:'DEMO-B',name:'Sample complete employer',registrationNo:'EXAMPLE-002',parentId:null,parentName:null,archived:false,statutoryStatus:'complete'},{id:'demo-group',code:null,name:'Sample grouping node',registrationNo:null,parentId:null,parentName:null,archived:false,statutoryStatus:'not_required'}]}/></tbody></table></div></main></NextIntlClientProvider>;}
